void modified()
{
    next modified();

    if (FeatureStateProvider::isFeatureEnabled(GUPGlobalEnableFeature::instance()))
    {
        PurchLine purchLine = element.purchLine;
        if (purchLine.orig().PurchPrice != purchLine.PurchPrice)
        {
            purchLine.ItemBasePriceRecId = 0;
        }
    }
}
